		"./cities/hokkaido.json": hokkaido_default,
		"./cities/hokuriku.json": hokuriku_default,
		"./cities/japan-national.json": japan_national_default,
		"./cities/kansai.json": kansai_default,
		"./cities/nagoya.json": nagoya_default,
		"./cities/nakaumi.json": nakaumi_default,
		"./cities/okinawa.json": okinawa_default,
		"./cities/sapporo.json": sapporo_default,
